                {
                    int next = text.AsSpan(i).IndexOfAnyInRange('\uD800', '\uDBFF');
                    if (next < 0) break;
                    i += next;
                    if (char.IsSurrogatePair(text, i)) { (pairs ??= new List<int>()).Add(i); i++; }
                    i++;
