        /// <summary>A replacement template: literal text and group references (\1, \g&lt;name&gt;, \g&lt;0&gt;), with Python's escapes.</summary>
        sealed class Template
        {
            readonly List<object> _parts = new List<object>(); // string or int (group number)

            public static Template Parse(string repl, Pattern p)
            {
                var t = new Template();
                var lit = new StringBuilder();
                void Flush() { if (lit.Length > 0) { t._parts.Add(lit.ToString()); lit.Clear(); } }
                for (int i = 0; i < repl.Length; i++)
                {
                    char c = repl[i];
                    if (c != '\\' || i + 1 >= repl.Length) { lit.Append(c); continue; }
                    char e = repl[++i];
                    if (e == 'g' && i + 1 < repl.Length && repl[i + 1] == '<')
                    {
                        int close = repl.IndexOf('>', i + 2);
                        if (close < 0) throw new error("missing >, unterminated name", repl, i);
                        string name = repl.Substring(i + 2, close - i - 2);
                        int g = int.TryParse(name, out var num) ? num : p.groupindex.TryGetValue(name, out var gi) ? (int)gi : throw new IndexOutOfRangeException($"unknown group name '{name}'");
                        if (g > p.groups) throw new error($"invalid group reference {g}", repl, i);
                        Flush(); t._parts.Add(g);
                        i = close;
                    }
                    else if (char.IsAsciiDigit(e))
                    {
                        int g = e - '0';
                        if (i + 1 < repl.Length && char.IsAsciiDigit(repl[i + 1]) && g * 10 + (repl[i + 1] - '0') <= p.groups) g = g * 10 + (repl[++i] - '0');
                        if (g > p.groups) throw new error($"invalid group reference {g}", repl, i);
                        Flush(); t._parts.Add(g);
                    }
                    else
                    {
                        switch (e)
                        {
                            case 'n': lit.Append('\n'); break;
                            case 't': lit.Append('\t'); break;
                            case 'r': lit.Append('\r'); break;
                            case 'f': lit.Append('\f'); break;
                            case 'v': lit.Append('\v'); break;
                            case 'a': lit.Append('\a'); break;
                            case 'b': lit.Append('\b'); break;
                            case '\\': lit.Append('\\'); break;
                            default:
                                if (char.IsAsciiLetter(e)) throw new error($"bad escape \\{e}", repl, i - 1);
                                lit.Append('\\').Append(e); // \& and other unknown non-letter escapes stay as written
                                break;
                        }
                    }
                }
                Flush();
                return t;
            }

            public string Expand(Match m)
            {
                if (_parts.Count == 1 && _parts[0] is string only) return only;
                var sb = new StringBuilder();
                foreach (var part in _parts) sb.Append(part is string s ? s : m.group((long)(int)part) ?? "");
                return sb.ToString();
