            {
                foreach (char f in lead.Groups[1].Value)
                    flags |= f switch { 'a' => ASCII, 'i' => IGNORECASE, 'L' => LOCALE, 'm' => MULTILINE, 's' => DOTALL, 'u' => UNICODE, 'x' => VERBOSE, _ => 0 };
                p = p.Substring(lead.Length);
            }
            bool ascii = binary || (flags & ASCII) != 0, verbose = (flags & VERBOSE) != 0;
            for (int i = 0; i < p.Length; i++)
            {
                char c = p[i];
                if (c == '\\' && i + 1 < p.Length)
                {
                    char e = p[++i];
                    if (inClass)
                    {
                        if (ascii && e == 'd') sb.Append("0-9");
                        else if (ascii && e == 'w') sb.Append("a-zA-Z0-9_");
                        else if (ascii && e == 's') sb.Append(@" \t\n\r\f\v");
                        else sb.Append('\\').Append(e);
                        continue;
                    }
                    switch (e)
                    {
                        case 'Z': sb.Append(@"\z"); break;
                        case 'd' when ascii: sb.Append("[0-9]"); break;
                        case 'D' when ascii: sb.Append("[^0-9]"); break;
                        case 'w' when ascii: sb.Append("[a-zA-Z0-9_]"); break;
                        case 'W' when ascii: sb.Append("[^a-zA-Z0-9_]"); break;
                        case 's' when ascii: sb.Append(@"[ \t\n\r\f\v]"); break;
                        case 'S' when ascii: sb.Append(@"[^ \t\n\r\f\v]"); break;
                        case 'U':
                            if (p.Length - i - 1 >= 8 && int.TryParse(p.AsSpan(i + 1, 8), System.Globalization.NumberStyles.HexNumber, null, out var cp))
                            {
                                sb.Append(NetRegex.Escape(char.ConvertFromUtf32(cp)));
                                i += 8;
                            }
                            else sb.Append(@"\U");
                            break;
                        default: sb.Append('\\').Append(e); break;
                    }
                    continue;
                }
                if (inClass)
                {
                    if (c == ']') { inClass = false; sb.Append(']'); }
                    else if (c == '[') sb.Append(@"\["); // literal in Python; .NET could read -[...] as class subtraction
                    else sb.Append(c);
                    continue;
                }
                if (verbose && c == '#')
                {
                    int nl = p.IndexOf('\n', i);
                    int stop = nl < 0 ? p.Length : nl;
                    sb.Append(p, i, stop - i);
                    i = stop - 1;
                    continue;
                }
                switch (c)
                {
                    case '.' when !binary:
                        sb.Append(UnicodeDot);
                        break;
                    case '[':
                        inClass = true;
                        sb.Append('[');
                        if (i + 1 < p.Length && p[i + 1] == '^') { sb.Append('^'); i++; }
                        if (i + 1 < p.Length && p[i + 1] == ']') { sb.Append(@"\]"); i++; }
                        break;
                    case '(':
                        if (i + 1 < p.Length && p[i + 1] == '?')
                        {
                            if (i + 2 < p.Length && p[i + 2] == '#')
                            {
                                int close = i + 3;
                                while (close < p.Length && p[close] != ')')
                                    close += p[close] == '\\' && close + 1 < p.Length ? 2 : 1;
                                if (close == p.Length) throw new error("missing ), unterminated comment", p, i);
                                sb.Append("(?#)");
                                i = close;
                            }
                            else if (i + 2 < p.Length && p[i + 2] == 'P' && i + 3 < p.Length && p[i + 3] == '<')
                            {
                                int close = p.IndexOf('>', i + 4);
                                if (close < 0) throw new error("missing >, unterminated name", p, i);
                                names[p.Substring(i + 4, close - i - 4)] = ++groupCount;
                                sb.Append('(');
                                i = close;
                            }
                            else if (i + 2 < p.Length && p[i + 2] == 'P' && i + 3 < p.Length && p[i + 3] == '=')
                            {
                                int close = p.IndexOf(')', i + 4);
                                if (close < 0) throw new error("missing ), unterminated name", p, i);
                                string name = p.Substring(i + 4, close - i - 4);
                                if (!names.TryGetValue(name, out var g)) throw new error($"unknown group name '{name}'", p, i);
                                sb.Append(@"\k<").Append(g).Append('>');
                                i = close;
                            }
                            else if (i + 2 < p.Length && p[i + 2] == '(')
                            {
                                // (?(name)yes|no) / (?(1)yes|no)
                                int close = p.IndexOf(')', i + 3);
                                string cond = close < 0 ? "" : p.Substring(i + 3, close - i - 3);
                                sb.Append("(?(").Append(names.TryGetValue(cond, out var cg) ? cg.ToString() : cond).Append(')');
                                i = close;
                            }
                            else if (i + 2 < p.Length && "aiLmsux-".IndexOf(p[i + 2]) >= 0)
                            {
                                // scoped inline flags (?i:...) / (?-i:...): .NET has no a, L, u
                                int j = i + 2;
                                var kept = new StringBuilder();
                                while (j < p.Length && "aiLmsux-".IndexOf(p[j]) >= 0) { if ("aLu".IndexOf(p[j]) < 0) kept.Append(p[j]); j++; }
                                string k = kept.ToString().TrimEnd('-');
                                if (j < p.Length && p[j] == ':') sb.Append(k.Length > 0 ? "(?" + k + ":" : "(?:");
                                else sb.Append(k.Length > 0 ? "(?" + k + ")" : "(?:)");
                                i = j;
                            }
                            else sb.Append('('); // (?: (?= (?! (?<= (?<! (?>
                        }
                        else { groupCount++; sb.Append('('); }
                        break;
                    case '{':
                        // {,n} means {0,n} in Python
                        if (i + 1 < p.Length && p[i + 1] == ',' && System.Text.RegularExpressions.Regex.IsMatch(p.Substring(i), @"^\{,\d+\}")) sb.Append("{0");
                        else sb.Append('{');
                        break;
                    default: sb.Append(c); break;
                }
            }
            return PossessiveRepetitions(sb.ToString(), verbose);
        }

        // .NET's atomic group expresses Python's possessive repetition without adding any captures.
        static string PossessiveRepetitions(string pattern, bool verbose)
        {
            if (!pattern.Contains("*+") && !pattern.Contains("++") &&
                !pattern.Contains("?+") && !pattern.Contains("}+")) return pattern;
            var result = new StringBuilder(pattern.Length);
            var groups = new Stack<int>();
            int atom = -1;
            for (int i = 0; i < pattern.Length;)
            {
                int first = i;
                char c = pattern[i++];
                if (c == '\\' && i < pattern.Length)
                {
                    char escape = pattern[i++];
                    if (escape is 'p' or 'P' or 'k' && i < pattern.Length && pattern[i] is '{' or '<')
                    {
                        int end = pattern.IndexOf(pattern[i] == '{' ? '}' : '>', i + 1);
                        if (end >= 0) i = end + 1;
                    }
                    else if (escape is 'x' or 'u')
                        i = Math.Min(pattern.Length, i + (escape == 'x' ? 2 : 4));
                    else if (char.IsAsciiDigit(escape))
                        while (i < pattern.Length && char.IsAsciiDigit(pattern[i])) i++;
                    atom = escape is 'A' or 'Z' or 'z' or 'b' or 'B' or 'G' ? -1 : result.Length;
                }
                else if (c == '[')
                {
                    while (i < pattern.Length)
                    {
                        char member = pattern[i++];
                        if (member == '\\' && i < pattern.Length) i++;
                        else if (member == ']') break;
                    }
                    atom = result.Length;
                }
                else if (verbose && c == '#')
                {
                    int end = pattern.IndexOf('\n', i);
                    i = end < 0 ? pattern.Length : end;
                }
                else if (c == '(')
                {
                    groups.Push(result.Length);
                    atom = -1;
                }
                else if (c == ')')
                    atom = groups.TryPop(out int opening) ? opening : -1;
                else if (c is '^' or '$' or '|')
                    atom = -1;
                else if (!(verbose && char.IsWhiteSpace(c)))
                {
                    int end = QuantifierEnd(pattern, first);
                    bool quantifier = end > first;
                    if (quantifier) i = end;
                    if (quantifier && atom >= 0 && i < pattern.Length && pattern[i] == '+')
                    {
                        int next = i + 1;
                        if (verbose)
                        {
                            while (next < pattern.Length)
                            {
                                if (char.IsWhiteSpace(pattern[next])) next++;
                                else if (pattern[next] == '#')
                                {
                                    int newline = pattern.IndexOf('\n', next + 1);
                                    next = newline < 0 ? pattern.Length : newline + 1;
                                }
                                else break;
                            }
                        }
                        if (QuantifierEnd(pattern, next) > next) throw new ArgumentException("multiple repeat");
                        result.Insert(atom, "(?>");
                        result.Append(pattern, first, i - first).Append(')');
                        i++;
                        atom = -1;
                        continue;
                    }
                    atom = quantifier ? -1 : result.Length;
                }
                result.Append(pattern, first, i - first);
            }
            return result.ToString();
        }

        static int QuantifierEnd(string pattern, int start)
        {
            if (start >= pattern.Length) return start;
            if (pattern[start] is '*' or '?' or '+') return start + 1;
            int end = start + 1;
            if (pattern[start] != '{' || end >= pattern.Length || !char.IsAsciiDigit(pattern[end])) return start;
            while (end < pattern.Length && char.IsAsciiDigit(pattern[end])) end++;
            if (end < pattern.Length && pattern[end] == ',')
            {
                end++;
                while (end < pattern.Length && char.IsAsciiDigit(pattern[end])) end++;
            }
            return end < pattern.Length && pattern[end] == '}' ? end + 1 : start;
        }
    }
}
